using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: index → bit-reversed byte
    private static readonly byte[] LookupTable = CreateLookupTable();

    private static byte[] CreateLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int b = i;
            b = ((b & 0xF0) >> 4) | ((b & 0x0F) << 4);
            b = ((b & 0xCC) >> 2) | ((b & 0x33) << 2);
            b = ((b & 0xAA) >> 1) | ((b & 0x55) << 1);
            table[i] = (byte)b;
        }
        return table;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        // Nibble-reverse lookup: index 0–15 maps nibble to its bit-reversed value
        // e.g. 0b0000→0b0000, 0b0001→0b1000, 0b0010→0b0100, ...
        ReadOnlySpan<byte> nibbleLut =
        [
            0x00, 0x08, 0x04, 0x0C,
            0x02, 0x0A, 0x06, 0x0E,
            0x01, 0x09, 0x05, 0x0D,
            0x03, 0x0B, 0x07, 0x0F
        ];

        int i = 0;

        if (Avx2.IsSupported && data.Length >= 32)
        {
            // Broadcast the 16-byte nibble LUT into both 128-bit lanes
            var lut = Vector256.Create(Vector128.Create(nibbleLut), Vector128.Create(nibbleLut));
            var lowNibbleMask = Vector256.Create((byte)0x0F);

            ref byte ptr = ref MemoryMarshal.GetReference(data);
            int lastBlockStart = data.Length - 32;

            for (; i <= lastBlockStart; i += 32)
            {
                var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);

                // Split each byte into low/high nibbles
                var lo = vec & lowNibbleMask;
                var hi = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & lowNibbleMask;

                // Reverse each nibble via shuffle lookup, then swap positions
                var reversedLo = Avx2.Shuffle(lut, lo);  // was low nibble → becomes high
                var reversedHi = Avx2.Shuffle(lut, hi);  // was high nibble → becomes low

                var result = Vector256.ShiftLeft(reversedLo.AsUInt16(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }
        else if (Ssse3.IsSupported && data.Length >= 16)
        {
            var lut = Vector128.Create(nibbleLut);
            var lowNibbleMask = Vector128.Create((byte)0x0F);

            ref byte ptr = ref MemoryMarshal.GetReference(data);
            int lastBlockStart = data.Length - 16;

            for (; i <= lastBlockStart; i += 16)
            {
                var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);

                var lo = vec & lowNibbleMask;
                var hi = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & lowNibbleMask;

                var reversedLo = Ssse3.Shuffle(lut, lo);
                var reversedHi = Ssse3.Shuffle(lut, hi);

                var result = Vector128.ShiftLeft(reversedLo.AsUInt16(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }
        else if (AdvSimd.IsSupported && data.Length >= 16)
        {
            var lut = Vector128.Create(nibbleLut);
            var lowNibbleMask = Vector128.Create((byte)0x0F);

            ref byte ptr = ref MemoryMarshal.GetReference(data);
            int lastBlockStart = data.Length - 16;

            for (; i <= lastBlockStart; i += 16)
            {
                var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);

                var lo = vec & lowNibbleMask;
                var hi = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & lowNibbleMask;

                // AdvSimd lookup table uses the low 4 bits of each byte
                var reversedLo = AdvSimd.Arm64.VectorTableLookup(lut, lo);
                var reversedHi = AdvSimd.Arm64.VectorTableLookup(lut, hi);

                var result = Vector128.ShiftLeft(reversedLo.AsUInt16(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }

        // Scalar tail using the precomputed 256-byte lookup table
        ref byte tableRef = ref MemoryMarshal.GetArrayDataReference(LookupTable);
        for (; i < data.Length; i++)
        {
            data[i] = Unsafe.Add(ref tableRef, data[i]);
        }
    }
}

